SET local check_function_bodies = off;

CREATE EXTENSION "hypopg" SCHEMA "extensions";

CREATE EXTENSION "index_advisor" SCHEMA "extensions";

CREATE EXTENSION "postgis" SCHEMA "extensions";

CREATE TABLE "public"."Contacts" (
  "ContactID"      bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "OrganizationID" bigint NOT NULL,
  "Email"          text   NOT NULL DEFAULT ''::text,
  "FirstName"      text   DEFAULT ''::text,
  "LastName"       text   DEFAULT ''::text,
  "ContactNotes"   text   DEFAULT ''::text,
  CONSTRAINT "Contacts_pkey" PRIMARY KEY ("ContactID")
);

ALTER TABLE "public"."Contacts"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."DeviceManufacturers" (
  "ManufacturerID"    bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "ManufacturerName"  text   NOT NULL DEFAULT ''::text,
  "ManufacturerNotes" text   DEFAULT ''::text,
  CONSTRAINT "DeviceManufacturers_ManufacturerName_key" UNIQUE ("ManufacturerName"),
  CONSTRAINT "DeviceManufacturers_pkey" PRIMARY KEY ("ManufacturerID")
);

ALTER TABLE "public"."DeviceManufacturers"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."DeviceSpecifications" (
  "DeviceSpecificationID" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "ManufacturerID"        bigint NOT NULL,
  "ModelNumber"           text   DEFAULT ''::text,
  "ModelName"             text   DEFAULT ''::text,
  "ModelNotes"            text   DEFAULT ''::text,
  CONSTRAINT "DeviceSpecifications_pkey" PRIMARY KEY ("DeviceSpecificationID")
);

ALTER TABLE "public"."DeviceSpecifications"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."MeasurementUnits" (
  "MeasurementUnitsID" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "UnitName"           text   DEFAULT ''::text,
  "UnitSymbol"         text   DEFAULT ''::text,
  CONSTRAINT "MeasurementUnits_UnitName_key" UNIQUE ("UnitName"),
  CONSTRAINT "MeasurementUnits_UnitSymbol_key" UNIQUE ("UnitSymbol"),
  CONSTRAINT "MeasurementUnits_pkey" PRIMARY KEY ("MeasurementUnitsID")
);

ALTER TABLE "public"."MeasurementUnits"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."ObservationTypes" (
  "ObservationTypeID" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "ObservationType"   text   DEFAULT ''::text,
  CONSTRAINT "ObservationTypes_ObservationType_key" UNIQUE ("ObservationType"),
  CONSTRAINT "ObservationTypes_pkey" PRIMARY KEY ("ObservationTypeID")
);

ALTER TABLE "public"."ObservationTypes"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."OrganizationProjects" (
  "ProjectID"      bigint  GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "OrganizationID" bigint  NOT NULL,
  "ProjectName"    text    NOT NULL DEFAULT ''::text,
  "StartDate"      date,
  "EndDate"        date,
  "IsOngoing"      boolean,
  "ProjectNotes"   text    DEFAULT ''::text,
  CONSTRAINT "OrganizationProjects_ProjectName_key" UNIQUE ("ProjectName"),
  CONSTRAINT "OrganizationProjects_pkey" PRIMARY KEY ("ProjectID")
);

ALTER TABLE "public"."OrganizationProjects"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."Organizations" (
  "OrganizationID"   bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "OrganizationName" text   NOT NULL DEFAULT ''::text,
  CONSTRAINT "Organizations_OrganizationName_key" UNIQUE ("OrganizationName"),
