CREATE TABLE "public"."SensorsToSpecs" (
  "SensorID"              bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "DeviceSpecificationID" bigint NOT NULL,
  "SerialNumber"          text,
  CONSTRAINT "SensorsToSpecs_pkey" PRIMARY KEY ("SensorID", "DeviceSpecificationID")
);

ALTER TABLE "public"."SensorsToSpecs"
