CREATE TABLE "public"."Sensors" (
  "SensorID"          bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "SensorName"        text   NOT NULL DEFAULT ''::text,
  "SensorNotes"       text   DEFAULT ''::text,
  "SensorObservation" text   DEFAULT ''::text,
  "ObservationTypeID" bigint,
  CONSTRAINT "Sensors_SensorName_key" UNIQUE ("SensorName"),
  CONSTRAINT "Sensors_pkey" PRIMARY KEY ("SensorID")
);

ALTER TABLE "public"."Sensors"
