CREATE TABLE "public"."StationObservations" (
  "StationID"         bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "ObservationTypeID" bigint NOT NULL,
  CONSTRAINT "StationObservations_pkey" PRIMARY KEY ("StationID", "ObservationTypeID")
);

ALTER TABLE "public"."StationObservations"
