CREATE TABLE "public"."StationSites" (
  "SiteID"             bigint               GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "SiteName"           text                 DEFAULT ''::text,
  "CoordinateLocation" extensions.geography NOT NULL,
  "Longitude"          numeric              NOT NULL,
  "Latitude"           numeric              NOT NULL,
  "Elevation"          bigint,
  "SiteNotes"          text                 DEFAULT ''::text,
  CONSTRAINT "StationSites_CoordinateLocation_key" UNIQUE ("CoordinateLocation"),
  CONSTRAINT "StationSites_pkey" PRIMARY KEY ("SiteID")
);

ALTER TABLE "public"."StationSites"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."StationTypes" (
  "TypeID"    bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "TypeName"  text   NOT NULL DEFAULT ''::text,
  "TypeNotes" text   DEFAULT ''::text,
