  CONSTRAINT "StationTypes_pkey" PRIMARY KEY ("TypeID")
);

ALTER TABLE "public"."StationTypes"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."StationsToSensors" (
  "StationID"                bigint   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "SensorID"                 bigint   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "PlacementHeight (Meters)" real,
  "PlacementNotes"           text     DEFAULT ''::text,
  "Count"                    smallint,
  "MeasurementUnitsID"       bigint,
  CONSTRAINT "StationsToSensors_pkey" PRIMARY KEY ("StationID", "SensorID")
);

ALTER TABLE "public"."StationsToSensors"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."StationsToSpecs" (
  "StationID"             bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "DeviceSpecificationID" bigint NOT NULL,
  "SerialNumber"          text,
