);

ALTER TABLE "public"."StationsToSpecs"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."Stations" (
  "StationID"          bigint              GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "ProjectID"          bigint,
  "SiteID"             bigint,
  "StationTypeID"      bigint,
  "StationName"        text                NOT NULL DEFAULT ''::text,
  "StationCode"        text                DEFAULT ''::text,
  "InstallDate"        date,
  "WebLink"            text                DEFAULT ''::text,
  "MesoWestLink"       text                DEFAULT ''::text,
  "IsActive"           boolean,
  "IsRealTime"         boolean,
  "IsSeasonal"         boolean,
  "UpdateInterval"     text                DEFAULT ''::text,
  "TransmitTime"       text                DEFAULT ''::text,
  "CoordinateLocation" extensions.geometry,
  "Longitude"          numeric             NOT NULL,
  "Latitude"           numeric             NOT NULL,
  "Elevation (FT)"     bigint,
  "StationNotes"       text                DEFAULT ''::text,
  CONSTRAINT "Stations_pkey" PRIMARY KEY ("StationID")
);

ALTER TABLE "public"."Stations"
  ENABLE ROW LEVEL SECURITY;

CREATE TYPE "public"."OBSERVATION_QUALITY_FLAG" AS ENUM (
  'unknown',
  'reliable',
  'questionable',
  'unreliable'
);

ALTER TABLE "public"."StationObservations"
  ADD COLUMN "Quality" public."OBSERVATION_QUALITY_FLAG";

CREATE TYPE "public"."ORGANIZATION_TYPE" AS ENUM (
  'non-profit',
  'private-company',
  'educational-institution',
  'tribal-government',
  'federal-government',
  'state-government',
  'international-government',
  'military'
);

ALTER TABLE "public"."Organizations"
  ADD COLUMN "OrganizationType" public."ORGANIZATION_TYPE";

ALTER TABLE "public"."Organizations"
  ADD COLUMN "OrganizationNotes" text DEFAULT ''::text;

ALTER TABLE "public"."DeviceSpecifications"
  ADD CONSTRAINT "DeviceSpecifications_ManufacturerID_fkey" FOREIGN KEY ("ManufacturerID") REFERENCES public."DeviceManufacturers"("ManufacturerID") ON UPDATE CASCADE;

ALTER TABLE "public"."Contacts"
  ADD CONSTRAINT "Contacts_OrganizationID_fkey" FOREIGN KEY ("OrganizationID") REFERENCES public."Organizations"("OrganizationID") ON UPDATE CASCADE;

ALTER TABLE "public"."OrganizationProjects"
