ALTER TABLE "public"."Sensors"
  ADD CONSTRAINT "Sensors_ObservationTypeID_fkey" FOREIGN KEY ("ObservationTypeID") REFERENCES public."ObservationTypes"("ObservationTypeID") ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE "public"."SensorsToSpecs"
  ADD CONSTRAINT "SensorsToSpecs_DeviceSpecificationID_fkey" FOREIGN KEY ("DeviceSpecificationID") REFERENCES public."DeviceSpecifications"("DeviceSpecificationID")
    ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE "public"."SensorsToSpecs"
  ADD CONSTRAINT "SensorsToSpecs_SensorID_fkey" FOREIGN KEY ("SensorID") REFERENCES public."Sensors"("SensorID") ON UPDATE CASCADE ON DELETE CASCADE;

