ALTER TABLE "public"."Stations"
  ADD CONSTRAINT "Stations_ProjectID_fkey" FOREIGN KEY ("ProjectID") REFERENCES public."OrganizationProjects"("ProjectID") ON UPDATE CASCADE ON DELETE SET NULL;

ALTER TABLE "public"."Stations"
  ADD CONSTRAINT "Stations_SiteID_fkey" FOREIGN KEY ("SiteID") REFERENCES public."StationSites"("SiteID") ON UPDATE CASCADE ON DELETE SET NULL;

ALTER TABLE "public"."Stations"
  ADD CONSTRAINT "Stations_StationTypeID_fkey" FOREIGN KEY ("StationTypeID") REFERENCES public."StationTypes"("TypeID") ON UPDATE CASCADE ON DELETE SET NULL;

ALTER TABLE "public"."StationContact"
  ADD CONSTRAINT "StationContact_StationID_fkey" FOREIGN KEY ("StationID") REFERENCES public."Stations"("StationID") ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE "public"."StationObservations"
  ADD CONSTRAINT "StationObservations_StationID_fkey" FOREIGN KEY ("StationID") REFERENCES public."Stations"("StationID") ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE "public"."StationOrganizationRole"
  ADD CONSTRAINT "StationOrganizationRole_StationID_fkey" FOREIGN KEY ("StationID") REFERENCES public."Stations"("StationID") ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE "public"."StationsToSensors"
