ALTER TABLE "public"."StationsToSensors"
  ADD CONSTRAINT "StationsToSensors_SensorID_fkey" FOREIGN KEY ("SensorID") REFERENCES public."Sensors"("SensorID") ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE "public"."StationsToSensors"
  ADD CONSTRAINT "StationsToSensors_StationID_fkey" FOREIGN KEY ("StationID") REFERENCES public."Stations"("StationID") ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE "public"."StationsToSpecs"
  ADD CONSTRAINT "StationsToSpecs_DeviceSpecificationID_fkey" FOREIGN KEY ("DeviceSpecificationID") REFERENCES public."DeviceSpecifications"("DeviceSpecificationID")
    ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE "public"."StationsToSpecs"
  ADD CONSTRAINT "StationsToSpecs_StationID_fkey" FOREIGN KEY ("StationID") REFERENCES public."Stations"("StationID") ON UPDATE CASCADE ON DELETE CASCADE;

COMMENT ON EXTENSION "hypopg" IS 'Hypothetical indexes for PostgreSQL';

COMMENT ON EXTENSION "index_advisor" IS 'Query index advisor';

COMMENT ON EXTENSION "postgis" IS 'PostGIS geometry and geography spatial types and functions';

COMMENT ON TABLE "public"."Contacts" IS 'Contacts are associated with an Organization where they are employed and tied to a Role when related to a Station.';

COMMENT ON TABLE "public"."DeviceManufacturers" IS 'Manufacturers of Sensors and/or Stations models.';

COMMENT ON TABLE "public"."ObservationTypes" IS 'Types of environmental observations that are present. Associated with different sensors, but also with Stations as a whole. This means that even if detailed sensor information is not provided, stations can still be associated with certain observations.';

COMMENT ON TABLE "public"."OrganizationProjects" IS 'Projects that are headed by an organization. Each project may be associated with one or more Stations.';

COMMENT ON TABLE "public"."Organizations" IS 'Organizations that are associated with Stations. An Organization is tied to a Role when linked to a Station.';

COMMENT ON TABLE "public"."Sensors" IS 'Table to house the information regarding specific Sensors. Placement on the station and relationships with specifications, units, and obersvation types.';

COMMENT ON TABLE "public"."SensorsToSpecs" IS 'Linking table relating Sensors to their DeviceSpecifications.';

COMMENT ON TABLE "public"."StationContact" IS 'Linking table that assigns each station a Contact person. This relationship is tied to a specific role regarding the station. Most often will be maintainer.';

COMMENT ON TABLE "public"."StationObservations" IS 'Linking table relating Stations to ObservationTypes. Some redundancy with StationSensors, to account for Stations with minimal sensor information provided.';

COMMENT ON TABLE "public"."StationOrganizationRole" IS 'Linking table relating Organizations to their Roles for Stations.';

COMMENT ON TABLE "public"."StationRoles" IS 'Contains the possible role relationships that an Organization can have towards a Station. Contacts are tied to a specific Role when they are linked to a Station.';

COMMENT ON TABLE "public"."StationSites" IS 'Geographic locations where Stations are placed. May contain more than one Station.';

COMMENT ON TABLE "public"."Stations" IS 'The "primary" table of this schema. Holds core information regarded the environmental sensors. Links to almost every corner of the schema for station specs, organization relationships, contacts, and more.';

COMMENT ON TABLE "public"."StationsToSensors" IS 'Linking table between Stations and Sensors. Contains placement information, measurement units, and type of observation.';

COMMENT ON TABLE "public"."StationsToSpecs" IS 'Linking table relating Stations to their DeviceSpecifications.';

COMMENT ON TYPE "public"."OBSERVATION_QUALITY_FLAG" IS 'Flag to be applied to Sensor Observations. Describes the reliability of the data.';

COMMENT ON TYPE "public"."ORGANIZATION_TYPE" IS 'Possible types of Organizations that could be linked to Projects, Stations, and Contacts.';

